import numpy as np

def kernel(x, w, stride, dilation):
    C_in, L = x.shape
    C_out, _, K = w.shape
    L_out = (L - dilation * (K - 1) - 1) // stride + 1

    out = np.zeros((C_out, L_out), dtype=np.float32)

    for o in range(C_out):
        for t in range(L_out):
            for c in range(C_in):
                for k in range(K):
                    # Compute the index in x
                    x_idx = t * stride + k * dilation
                    if 0 <= x_idx < L:
                        out[o, t] += w[o, c, k] * x[c, x_idx]

    return out

